  avg *= ramPen.avg;
  low *= ramPen.low;
  const vramNeeded = estimateVramNeeded(RES_META[res].vramRes, PRESET_META[preset].vram, {
    rayTracing: false,
    frameGen: frameGen !== "off",
    hdTextures: false
  });
  // AUDIT FIX M6 (2026-11-17): ultrawide 1440p has ~34% more pixels than
  // 2560x1440, so its VRAM need is 1.34x the 1440p pool instead of equal.
  if (res === "ultrawide-1440p") {
    vramNeeded.totalGB = Math.round(vramNeeded.totalGB * 1.34 * 10) / 10;
  }
  const vramShortGB = Math.max(0, +(vramNeeded.totalGB - cardVramGB).toFixed(1));
